# The final snapshot feeds metrics and artifacts.  Replace its
# pre-liquidation mark with post-liquidation cash so terminal
# slippage and exit commission are reflected in reported equity.
if self.equity_snapshots:
    self.equity_snapshots[-1] = EquitySnapshot(
        timestamp=last_ts,
        capital=self.capital,
        unrealized=0.0,
        equity=self.capital,
        positions=0,
    )
if self.actual_position_snapshots:
    self.actual_position_snapshots[-1] = (
        last_ts, {code: 0.0 for code in codes}
    )

replacements.after:
# Unexecutable terminal exits remain open and marked, never cash.
final_equity = self._calc_equity(close_df, last_ts)
remaining_margin = sum(
    self._calc_margin(symbol, position.size, position.entry_price, position.leverage)
    for symbol, position in self.positions.items()
)
if self.equity_snapshots:
    self.equity_snapshots[-1] = EquitySnapshot(
        timestamp=last_ts,
        capital=self.capital,
        unrealized=final_equity - self.capital - remaining_margin,
        equity=final_equity,
        positions=len(self.positions),
    )
if self.actual_position_snapshots:
    self.actual_position_snapshots[-1] = (
        last_ts, self._actual_weights(close_df, last_ts, codes, final_equity)
    )
